unsigned char out[OUT_N];

void bench_init(void)
{
}

unsigned int bench(void)
{
    unsigned int i = 0, o = 0, n, off, s = 0;
    unsigned char tok, b;

    for (;;) {
        tok = lz[i++];
        n = tok >> 4;                       /* literal length */
        if (n == 15) {
            do {
                b = lz[i++];
                n += b;
            } while (b == 255);
        }
        while (n) {
            out[o++] = lz[i++];
            n--;
        }
        if (i >= LZ_N)                      /* the last sequence has no match */
            break;
        off = lz[i] | (lz[i + 1] << 8);
        i += 2;
        n = tok & 15;                       /* match length - 4 */
        if (n == 15) {
            do {
                b = lz[i++];
                n += b;
            } while (b == 255);
        }
        n += 4;
        while (n) {                         /* may overlap: byte at a time */
            out[o] = out[o - off];
            o++;
            n--;
        }
    }
    for (i = 0; i < o; i++)
        s += out[i];
    return s;
}
